const body = $json.body || {};
const action = body.action || 'login';
const email = (body.email || '').trim().toLowerCase();
const password = body.password || '';
const name = body.name || (email.split('@')[0]);

// 1. 基本資料驗證
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!email || !emailRegex.test(email)) {
  return [{
    json: {
      statusCode: 400,
      response: {
        success: false,
        message: '請輸入有效的電子信箱格式！'
      }
    }
  }];
}

if (!password || password.length < 6) {
  return [{
    json: {
      statusCode: 400,
      response: {
        success: false,
        message: '密碼長度必須至少為 6 個字元！'
      }
    }
  }];
}

// 2. 模擬成功產生 Token
const token = 'jwt_' + Buffer.from(email + ':' + Date.now()).toString('base64');

if (action === 'register') {
  return [{
    json: {
      statusCode: 200,
      response: {
        success: true,
        message: '會員註冊成功！歡迎加入極客數位。',
        token: token,
        user: {
          name: name,
          email: email,
          vipLevel: 'Standard'
        }
      }
    }
  }];
} else {
  return [{
    json: {
      statusCode: 200,
      response: {
        success: true,
        message: '登入成功！歡迎回來。',
        token: token,
        user: {
          name: name,
          email: email,
          vipLevel: 'Gold'
        }
      }
    }
  }];
}
